use super::*;
use crate::test_support::{compiled_fixture, scalar};
use assets::{CompiledMolangExpression, MolangBranch, MolangCall, MolangSymbol};

const QUERY: u32 = 1;
const TEXT_QUERY: u32 = 2;
const VARIABLE: u32 = 3;
const TEMP: u32 = 4;
const TEXT: u32 = 5;

struct Harness {
    assets: Arc<RuntimeEntityAssets>,
    fast: VariableLayout,
    generic: VariableLayout,
}

impl Harness {
    /// Admits generated bytecode with identical layouts for the typed and generic evaluators.
    fn new(ops: Vec<MolangOp>) -> Self {
        let mut compiled = compiled_fixture();
        compiled.molang_symbols = [
            (MolangSymbolKind::Name, "wield"),
            (MolangSymbolKind::Query, "query.anim_time"),
            (MolangSymbolKind::Query, "query.get_name"),
            (MolangSymbolKind::Variable, "variable.numeric"),
            (MolangSymbolKind::Temporary, "temp.numeric"),
            (MolangSymbolKind::String, "text"),
        ]
        .map(|(kind, identifier)| MolangSymbol {
            kind,
            identifier: identifier.into(),
        })
        .into();
        let first = CompiledMolangExpression {
            first_op: 0,
            op_count: ops.len() as u16,
            max_stack: assets::molang_program_stack(&ops).unwrap(),
        };
        let mut expressions = vec![first];
        let mut ops = ops;
        // The original fixture's render and animation data also reference expressions 1–3.
        for _ in 1..4 {
            expressions.push(CompiledMolangExpression {
                first_op: ops.len() as u32,
                op_count: 1,
                max_stack: 1,
            });
            ops.push(MolangOp::Push(scalar(0.0)));
        }
        compiled.molang_ops = ops.into();
        compiled.molang_expressions = expressions.into();
        let assets = Arc::new(RuntimeEntityAssets::from_compiled(compiled).unwrap());
        let fast = VariableLayout::new(&assets);
        let mut generic = VariableLayout::new(&assets);
        generic.numeric.clear();
        Self {
            assets,
            fast,
            generic,
        }
    }

    /// Compares exact values, charges, query work and effects, including every partial budget.
    fn compare(&self, value: MolangValue, query: f32, this: f32, exhaustive: bool) {
        self.compare_with(Some(value), [query, this], exhaustive, None, false);
    }

    /// Includes unset slots, retained query values and observed predicate execution.
    fn compare_with(
        &self,
        value: Option<MolangValue>,
        [query, this]: [f32; 2],
        exhaustive: bool,
        history: Option<&[(u32, MolangValue)]>,
        observed: bool,
    ) {
        let count = usize::from(self.assets.molang_expressions()[0].op_count);
        let limits: Vec<_> = if exhaustive {
            (0..=count + 1)
                .flat_map(|left| [(left, count + 1), (count + 1, left), (left, left)])
                .collect()
        } else {
            vec![(count + 1, count + 1)]
        };
        for (actor_limit, world_limit) in limits {
            let run = |layout: &VariableLayout| {
                let actor = crate::tests::actor_with_metadata(HashMap::new());
                let input = ActorTickInput::default();
                let context = ActorTickContext::default();
                let evaluator = Evaluator {
                    assets: &self.assets,
                    layout,
                    pack: false,
                    program: None,
                    actor: &actor,
                    input: &input,
                    context: &context,
                    anim_tick: 0,
                    anim_time: Some(query),
                    swell_amount: None,
                    presentation_alpha: None,
                    query_history: history,
                    life_tick: 0,
                    finished: (false, false),
                    state_time: 0.0,
                    bones: &[],
                    bone_names: &[],
                };
                let mut variables = layout.fresh(7);
                if let Some(value) = &value {
                    variables.assign_variable(0, value.clone());
                }
                variables
                    .store(Place::Temporary(0), MolangValue::Number(9.0))
                    .unwrap();
                let capture = variables.begin_effects();
                let mut world = world_limit;
                let mut budget = EvalBudget {
                    actor_left: actor_limit,
                    world_left: &mut world,
                    work_left: 13,
                    transitions_left: 17,
                    used: 0,
                    stack: Default::default(),
                    static_draw: Some(true),
                };
                take_query_work();
                let mut reads = ObservedInputs::new(&variables);
                let result = evaluator.run_observed(
                    0,
                    &mut variables,
                    this,
                    &mut budget,
                    observed.then_some(&mut reads),
                );
                let queries = take_query_work();
                let effects = variables.finish_effects(capture);
                let stopped_stack = result.is_err().then(|| {
                    budget
                        .stack
                        .0
                        .iter()
                        .cloned()
                        .map(value_bits)
                        .collect::<Vec<_>>()
                });
                (
                    result.map(value_bits),
                    stopped_stack,
                    (budget.actor_left, *budget.world_left, budget.used),
                    (
                        budget.work_left,
                        budget.transitions_left,
                        budget.static_draw,
                    ),
                    (queries, reads.weight()),
                    variables.read(Place::Variable(0)).map(value_bits),
                    variables.read(Place::Temporary(0)).map(value_bits),
                    variables.random_state(),
                    effects.random_draws,
                    effects
                        .writes
                        .into_iter()
                        .map(|(place, value)| {
                            (matches!(place, Place::Temporary(_)), value.map(value_bits))
                        })
                        .collect::<Vec<_>>(),
                )
            };
            assert_eq!(
                run(&self.fast),
                run(&self.generic),
                "actor={actor_limit}, world={world_limit}, query={query:?}, this={this:?}"
            );
        }
    }
}

/// Retains number bits, including signed zero and NaN payloads, in differential comparisons.
fn value_bits(value: MolangValue) -> (u8, u64, Option<Arc<str>>) {
    match value {
        MolangValue::Number(value) => (0, u64::from(value.to_bits()), None),
        MolangValue::ActorReference(id) => (1, id, None),
        MolangValue::String(value) => (2, 0, Some(value)),
    }
}

/// Generates recursive numeric expressions with branches joining at identical lane depths.
fn expression(seed: &mut u64, depth: u8, ops: &mut Vec<MolangOp>) {
    *seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
    let choice = (*seed >> 32) as usize;
    if depth == 0 {
        ops.push(match choice % 4 {
            0 => MolangOp::LoadQuery(QUERY),
            1 => MolangOp::LoadVariable(VARIABLE),
            2 => MolangOp::LoadThis,
            _ => MolangOp::Push(scalar((choice % 17) as f32 - 8.0)),
        });
        return;
    }
    expression(seed, depth - 1, ops);
    match choice % 5 {
        0 => ops.push(MolangOp::Call(MolangFunction::Cos)),
        1 => ops.push(MolangOp::Not),
        2 => {
            let branch = ops.len();
            ops.push(MolangOp::JumpIfFalse(0));
            expression(seed, depth - 1, ops);
            let jump = ops.len();
            ops.push(MolangOp::Jump(0));
            ops[branch] = MolangOp::JumpIfFalse(ops.len() as u16);
            expression(seed, depth - 1, ops);
            ops[jump] = MolangOp::Jump(ops.len() as u16);
        }
        _ => {
            expression(seed, depth - 1, ops);
            let operations = [
                MolangOp::Add,
                MolangOp::Subtract,
                MolangOp::Multiply,
                MolangOp::Divide,
                MolangOp::Equal,
                MolangOp::NotEqual,
                MolangOp::Less,
                MolangOp::LessEqual,
                MolangOp::Greater,
                MolangOp::GreaterEqual,
            ];
            ops.push(operations[choice % operations.len()]);
        }
    }
}

#[test]
fn generated_numeric_expressions_match_values_and_every_budget() {
    let inputs = [
        0.0,
        -0.0,
        1.0,
        -3.5,
        f32::EPSILON / 2.0,
        f32::MIN_POSITIVE,
        f32::MAX,
        f32::INFINITY,
        f32::NEG_INFINITY,
        f32::NAN,
        f32::from_bits(0xffc0_0123),
    ];
    let mut seed = 17;
    for index in 0..160 {
        let mut ops = Vec::new();
        expression(&mut seed, 3, &mut ops);
        if index % 2 == 0 {
            ops.push(MolangOp::Return);
        }
        let harness = Harness::new(ops);
        assert!(harness.fast.numeric[0].is_some());
        for (at, &value) in inputs.iter().enumerate() {
            harness.compare(
                MolangValue::Number(value),
                inputs[(at + index) % inputs.len()],
                inputs[(at + 3) % inputs.len()],
                true,
            );
        }
    }
}

#[test]
fn fused_load_boundaries_stop_at_the_same_semantic_instruction() {
    for source in [
        MolangOp::Push(scalar(-0.0)),
        MolangOp::LoadThis,
        MolangOp::LoadVariable(VARIABLE),
        MolangOp::LoadQuery(QUERY),
        MolangOp::CallQuery(MolangCall {
            symbol: QUERY,
            arguments: 0,
        }),
    ] {
        for operation in [
            MolangOp::Add,
            MolangOp::Subtract,
            MolangOp::Multiply,
            MolangOp::Divide,
            MolangOp::Equal,
            MolangOp::NotEqual,
            MolangOp::Less,
            MolangOp::LessEqual,
            MolangOp::Greater,
            MolangOp::GreaterEqual,
            MolangOp::Negate,
            MolangOp::Not,
            MolangOp::Truthy,
            MolangOp::Call(MolangFunction::Cos),
        ] {
            let mut ops = vec![MolangOp::LoadThis, source, operation];
            if matches!(
                operation,
                MolangOp::Negate | MolangOp::Not | MolangOp::Truthy | MolangOp::Call(_)
            ) {
                ops.push(MolangOp::Add);
            }
            let harness = Harness::new(ops);
            assert!(
                harness.fast.numeric[0]
                    .as_ref()
                    .unwrap()
                    .instructions
                    .iter()
                    .any(|op| op.cost == 2)
            );
            harness.compare(MolangValue::Number(-0.0), f32::INFINITY, -2.0, true);
        }
    }
}

#[test]
fn short_circuit_skips_queries_and_preserves_nan_truthiness() {
    for branch in [MolangOp::JumpIfFalse(4), MolangOp::JumpIfTrue(4)] {
        let harness = Harness::new(vec![
            MolangOp::LoadVariable(VARIABLE),
            branch,
            MolangOp::LoadQuery(QUERY),
            MolangOp::Jump(5),
            MolangOp::Push(scalar(-0.0)),
            MolangOp::Truthy,
        ]);
        assert!(harness.fast.numeric[0].is_some());
        for value in [0.0, -0.0, f32::NAN, f32::INFINITY, -2.0] {
            harness.compare(MolangValue::Number(value), f32::NAN, 0.0, true);
        }
    }
}

#[test]
fn mixed_values_and_effects_keep_the_generic_evaluator() {
    let cases = [
        vec![
            MolangOp::LoadThis,
            MolangOp::JumpIfFalse(4),
            MolangOp::PushString(TEXT),
            MolangOp::Jump(5),
            MolangOp::Push(scalar(0.0)),
            MolangOp::Truthy,
        ],
        vec![MolangOp::PushString(TEXT), MolangOp::Not],
        vec![MolangOp::LoadQuery(TEXT_QUERY), MolangOp::Truthy],
        vec![
            MolangOp::LoadVariable(VARIABLE),
            MolangOp::CallQuery(MolangCall {
                symbol: QUERY,
                arguments: 1,
            }),
        ],
        vec![MolangOp::LoadVariable(TEMP)],
        vec![
            MolangOp::Push(scalar(2.0)),
            MolangOp::StoreVariable(VARIABLE),
            MolangOp::LoadVariable(VARIABLE),
        ],
        vec![
            MolangOp::PushString(TEXT),
            MolangOp::StoreVariable(TEMP),
            MolangOp::LoadVariable(TEMP),
        ],
        vec![
            MolangOp::Push(scalar(0.0)),
            MolangOp::Push(scalar(1.0)),
            MolangOp::Call(MolangFunction::Random),
        ],
        vec![
            MolangOp::Coalesce(MolangBranch {
                symbol: VARIABLE,
                target: 2,
            }),
            MolangOp::LoadThis,
        ],
        vec![
            MolangOp::LoadVariable(VARIABLE),
            MolangOp::Arrow(3),
            MolangOp::LoadThis,
        ],
    ];
    for ops in cases {
        let harness = Harness::new(ops);
        assert!(harness.fast.numeric[0].is_none());
        harness.compare(MolangValue::Number(f32::NAN), -0.0, 2.0, true);
    }
    for op in [
        MolangOp::Equal,
        MolangOp::Not,
        MolangOp::Truthy,
        MolangOp::Add,
    ] {
        let mut ops = vec![MolangOp::LoadVariable(VARIABLE)];
        if matches!(op, MolangOp::Equal | MolangOp::Add) {
            ops.push(MolangOp::LoadThis);
        }
        ops.push(op);
        let harness = Harness::new(ops);
        assert!(harness.fast.numeric[0].is_some());
        for value in [
            MolangValue::String(Arc::from("")),
            MolangValue::ActorReference(1),
        ] {
            assert!(
                !harness.fast.numeric[0]
                    .as_ref()
                    .unwrap()
                    .variables
                    .is_empty()
            );
            harness.compare(value, 1.0, 0.0, true);
        }
    }
}

#[test]
fn math_calls_keep_operation_order_and_nonfinite_recovery() {
    for function in [
        MolangFunction::Abs,
        MolangFunction::Acos,
        MolangFunction::Asin,
        MolangFunction::Atan,
        MolangFunction::Atan2,
        MolangFunction::Ceil,
        MolangFunction::Clamp,
        MolangFunction::CopySign,
        MolangFunction::Exp,
        MolangFunction::Floor,
        MolangFunction::HermiteBlend,
        MolangFunction::InverseLerp,
        MolangFunction::Lerp,
        MolangFunction::LerpRotate,
        MolangFunction::Ln,
        MolangFunction::Max,
        MolangFunction::Min,
        MolangFunction::MinAngle,
        MolangFunction::Mod,
        MolangFunction::Pow,
        MolangFunction::Round,
        MolangFunction::Sign,
        MolangFunction::Sin,
        MolangFunction::Sqrt,
        MolangFunction::Trunc,
        MolangFunction::Ease(
            assets::MolangEaseCurve::Elastic,
            assets::MolangEaseMode::InOut,
        ),
    ] {
        let mut ops = vec![MolangOp::LoadVariable(VARIABLE)];
        if function.arity() > 1 {
            ops.push(MolangOp::LoadQuery(QUERY));
        }
        if function.arity() > 2 {
            ops.push(MolangOp::LoadThis);
        }
        ops.push(MolangOp::Call(function));
        let harness = Harness::new(ops);
        assert!(harness.fast.numeric[0].is_some());
        for a in [
            f32::NAN,
            f32::INFINITY,
            f32::NEG_INFINITY,
            -0.0,
            0.0,
            0.5,
            -2.0,
        ] {
            for b in [f32::NAN, -0.0, 0.0, 3.0] {
                harness.compare(MolangValue::Number(a), b, 0.25, true);
            }
        }
    }
}

#[test]
fn retained_query_types_unset_slots_and_observed_reads_match() {
    let harness = Harness::new(vec![
        MolangOp::LoadQuery(QUERY),
        MolangOp::LoadVariable(VARIABLE),
        MolangOp::Equal,
    ]);
    assert!(harness.fast.numeric[0].is_some());
    for retained in [
        MolangValue::Number(f32::NAN),
        MolangValue::Number(-0.0),
        MolangValue::String(Arc::from("")),
        MolangValue::ActorReference(17),
    ] {
        let history = [(QUERY, retained)];
        for observed in [false, true] {
            harness.compare_with(None, [7.0, -0.0], true, Some(&history), observed);
        }
    }
}

#[test]
fn completed_pose_histories_match_the_generic_evaluator() {
    let assets = crate::test_support::counting_random_assets();
    let mut fast = ActorAnimationStore::with_assets(Arc::clone(&assets));
    let mut generic = ActorAnimationStore::with_assets(assets);
    Arc::get_mut(&mut generic.layout).unwrap().numeric.clear();
    let mut actor = crate::tests::actor_with_metadata(HashMap::new());
    fast.insert(1, 0, &actor);
    generic.insert(1, 0, &actor);
    for tick in 0..24 {
        actor.previous_position = actor.position;
        actor.position[0] += 0.2;
        actor.velocity[0] = 4.0;
        actor.yaw = tick as f32 * 19.0;
        if tick % 6 == 0 {
            fast.start_swing(actor.runtime_id, 6, 6);
            generic.start_swing(actor.runtime_id, 6, 6);
        }
        let actors = HashMap::from([(actor.runtime_id, actor.clone())]);
        for store in [&mut fast, &mut generic] {
            store.advance_tick(&actors, None, None, true, false, |_| {
                ActorTickContext::default()
            });
        }
        assert_eq!(fast.stats(), generic.stats());
        assert_eq!(
            fast.get(actor.runtime_id).unwrap().current,
            generic.get(actor.runtime_id).unwrap().current
        );
        for alpha in [0.0, 0.25, 0.5, 0.75, 1.0] {
            for limit in [0, 1, 5, 17, MAX_MOLANG_OPS_PER_RENDER_FRAME] {
                let mut fast_left = limit;
                let mut generic_left = limit;
                let fast_layers =
                    fast.render_layers(&actor, alpha, [0.0; 2], [0.0; 3], &mut fast_left, true);
                let generic_layers = generic.render_layers(
                    &actor,
                    alpha,
                    [0.0; 2],
                    [0.0; 3],
                    &mut generic_left,
                    true,
                );
                assert_eq!(fast_left, generic_left);
                assert_eq!(
                    fast_layers.as_ref().map(|layers| &layers.render),
                    generic_layers.as_ref().map(|layers| &layers.render)
                );
                assert!(
                    fast_layers
                        .as_ref()
                        .is_none_or(|layers| layers.skin.is_empty())
                );
                assert!(
                    generic_layers
                        .as_ref()
                        .is_none_or(|layers| layers.skin.is_empty())
                );
                assert_eq!(fast.frame_fallbacks(), generic.frame_fallbacks());
            }
        }
    }
}
